def resolve_model_name(
    explicit: str | None = None,
    *,
    configured: str | None = None,
) -> str | None:
    """[CFG-5] model precedence: --model, LLM_MODEL, config, llm default.

    CLI beats env beats config -- [CFG-5]'s assembly order puts environment
    variables ABOVE the config file, so `LLM_MODEL` overrides
    `analyze.model` whenever --model is omitted.

    Returns ``None`` to mean "let ``llm`` use its configured default" so the
    lazy-import boundary stays in ``default_adapter``.
    """

    import os

    if explicit is not None and explicit.strip():
        return explicit.strip()
    env = os.environ.get("LLM_MODEL", "").strip()
    if env:
        return env
    if configured is not None and configured.strip():
        return configured.strip()
    return None

def _resolve_settings(args: argparse.Namespace) -> BackstitchSettings:
    """[CFG-5]: config discovery anchored at the resolved repo root."""

    if args.no_config and args.config is not None:
        msg = "--config and --no-config are mutually exclusive"
        raise ConfigLoadError(msg)
    if args.no_config:
        return load_settings(args.repo_root.resolve(), use_repo_config=False)
    return load_settings(args.repo_root.resolve(), explicit=args.config)

def _profile_from(
    args: argparse.Namespace, settings: BackstitchSettings
) -> ProfileConfig:
    """[CFG-5] precedence: CLI flags > config values > built-in profile."""

    # An explicit --profile beats config; config beats the built-in default.
    name = args.profile or settings.profile or "backstitch-style-v1"
    profile = _configured_profile(settings, name=name)
    cli_overrides: dict[str, tuple[str, ...]] = {}
    if args.spec_roots is not None:
        cli_overrides["spec_roots"] = tuple(args.spec_roots)
    if args.plan_roots is not None:
        cli_overrides["plan_roots"] = tuple(args.plan_roots)
    if args.code_roots is not None:
        cli_overrides["code_roots"] = tuple(
            expand_root_value(value) for value in args.code_roots
        )
    if args.test_roots is not None:
        cli_overrides["test_roots"] = tuple(
            expand_root_value(value) for value in args.test_roots
        )
    if cli_overrides:
        profile = profile.with_overrides(**cli_overrides)
    _validate_test_root_containment(args.repo_root.resolve(), profile)
    return profile

def _model_source(model_arg: str | None, configured: str | None) -> str:
    """Presentation of which [CFG-5] source won.

    Mirrors (never replaces) ``resolve_model_name``: the value always comes
    from that helper; this only labels the winning source for the report.
    """

    if model_arg is not None and model_arg.strip():
        return "--model"
    if os.environ.get("LLM_MODEL", "").strip():
        return "LLM_MODEL environment variable"
    if configured is not None and configured.strip():
        return "config [analyze].model"
    return "llm default model"

"""Sibling repository discovery for target corpus checks.

Spec: docs/specs/02-backstitch-core.md [SC-12]
Spec: docs/specs/03-backstitch-configuration.md [CFG-5], [CFG-6]

Discovery precedence: environment override, then configured
``[target_roots]`` path, then the sibling of the MAIN repository checkout.
The worktree case is the one that breaks in practice ([SC-12]): naive
``<checkout-parent>/<name>`` resolves to ``.worktrees/<name>`` from a linked
worktree, so worktree paths are normalized to the main repository root
before sibling lookup.
"""

from __future__ import annotations

import os
import subprocess
from pathlib import Path

from backstitch.settings import BackstitchSettings

_ENV_OVERRIDES = {
    "weft": "BACKSTITCH_WEFT_ROOT",
}


def git_worktree_root(start: Path | None = None) -> Path:
    """Return the root of the current git worktree."""

    start_path = (start or Path.cwd()).resolve()
    try:
        toplevel = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=start_path,
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except (subprocess.CalledProcessError, FileNotFoundError):
        return start_path
    return Path(toplevel).resolve()


def git_main_repo_root(start: Path | None = None) -> Path:
    """Normalize a worktree checkout path to the main repository root."""

    root = git_worktree_root(start)
    parts = root.parts
    if ".worktrees" in parts:
        index = parts.index(".worktrees")
        return Path(*parts[:index])
    return root


def discover_sibling_repo(
    name: str,
    *,
    anchor: Path | None = None,
    configured_path: str | None = None,
) -> Path | None:
    """Locate a sibling repository directory next to the main repo."""

    env_key = _ENV_OVERRIDES.get(name.lower())
    if env_key:
        override = os.environ.get(env_key)
        if override:
            path = Path(override).expanduser().resolve()
            if path.is_dir():
                return path

    if configured_path:
        path = Path(configured_path).expanduser().resolve()
        if path.is_dir():
            return path

    main_repo = git_main_repo_root(anchor)
    candidate = main_repo.parent / name
    if candidate.is_dir():
        return candidate.resolve()
    return None


def discover_weft(
    *,
    anchor: Path | None = None,
    settings: BackstitchSettings | None = None,
) -> Path | None:
    configured = settings.target_roots.weft if settings is not None else None
    return discover_sibling_repo("weft", anchor=anchor, configured_path=configured)
